Final expression: redirectUrl != null && !redirectUrl.trim().isEmpty() && redirectUrl.trim().startsWith("/") && !redirectUrl.trim().toLowerCase().contains("http:") && !redirectUrl.trim().toLowerCase().contains("https:") && !redirectUrl.trim().toLowerCase().contains("javascript:") && !redirectUrl.trim().toLowerCase().contains("data:") && !redirectUrl.trim().contains("..") && redirectUrl.trim().length() <= 1000
